import json,pathlib,zipfile,sys,hashlib,datetime
r=pathlib.Path(sys.argv[1] if len(sys.argv)>1 else 'outputs/CFN-Weekly-Recaps/2026-week11').resolve();manifest=json.loads((r/'manifest.json').read_text())
week=manifest[0]['week'];season=manifest[0]['season']
assert all(l['week']==week and l['season']==season for l in manifest)
for lg in manifest:
 filename=f'CFN-{lg["id"].upper()}-Week-{lg["week"]}-Recap.zip';lg['zip']=filename
 with zipfile.ZipFile(r/filename,'w',zipfile.ZIP_DEFLATED) as z:
  for i,s in enumerate(lg['slides'],1):z.write(r/s['png'],f'{i:02}-{s["title"].replace(" ","-")}.png')
with zipfile.ZipFile(r/f'CFN-All-Four-Leagues-Week-{week}.zip','w',zipfile.ZIP_DEFLATED) as z:
 for lg in manifest:
  for i,s in enumerate(lg['slides'],1):z.write(r/s['png'],f'{lg["name"]}/{i:02}-{s["title"].replace(" ","-")}.png')
(r/'manifest.json').write_text(json.dumps(manifest,indent=2,ensure_ascii=False))
data=json.dumps(manifest).replace('</','<\\/')
page='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>CFN Studio · Weekly Recaps</title><style>
*{box-sizing:border-box}body{margin:0;background:#0a1219;color:#edf3f6;font-family:-apple-system,BlinkMacSystemFont,Arial,sans-serif}main{max-width:1480px;margin:auto;padding:40px}header{display:flex;align-items:center;gap:18px;margin-bottom:32px}header img{width:50px;height:34px;object-fit:contain}h1{margin:0;font-size:30px;letter-spacing:-.8px}.muted{color:#95aab6;font-size:14px;line-height:1.6}.tools{display:flex;align-items:center;justify-content:space-between;gap:16px;flex-wrap:wrap}.leagues{display:flex;gap:7px;flex-wrap:wrap}button,a.pill{font:inherit;font-size:14px;border:1px solid #94b3c42b;background:#172731;color:#d8e3e9;border-radius:50px;padding:12px 17px;text-decoration:none;cursor:pointer}button[aria-pressed=true]{background:#23504f;color:#b8fff5;border-color:#63cdb773}button:focus-visible,a:focus-visible{outline:2px solid #6addce;outline-offset:3px}.summary{margin:24px 0 20px;display:flex;align-items:baseline;justify-content:space-between;gap:16px;flex-wrap:wrap}.summary h2{font-size:21px;margin:0;font-weight:550}.verified{color:#8cd6c4;font-size:13px}.slides{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:22px}.slide{min-width:0}.slide img{width:100%;height:auto;display:block;border:1px solid #8ba7b728;border-radius:12px;box-shadow:0 15px 35px #0005}.slide .caption{display:flex;justify-content:space-between;align-items:center;margin:15px 0 10px}.slide h3{font-size:15px;margin:0;font-weight:550}.slide a{color:#8ddad1;font-size:13px;text-decoration:none}.how{border-top:1px solid #91acbf22;margin-top:35px;padding-top:20px;max-width:850px}.how h2{font-size:17px}.how p{font-size:14px;line-height:1.6;color:#a6bbc8}.preview-label{font-size:11px;letter-spacing:1.5px;color:#83b5bb;margin-bottom:5px;text-transform:uppercase}@media(max-width:800px){main{padding:22px}.slides{grid-template-columns:1fr}.summary{display:block}.verified{margin-top:10px}.slide{max-width:540px}h1{font-size:24px}}
</style></head><body><main><header><img src="assets/crown.svg" alt="CFN"><div><div class="preview-label">Studio · Drafts for review</div><h1>Weekly recaps</h1></div></header><div class="tools"><nav class="leagues" aria-label="League"></nav><a class="pill" href="CFN-All-Four-Leagues-Week-__WEEK__.zip" download>Download all four leagues ↓</a></div><div class="summary"><h2 id="league-title"></h2><span class="verified">Week __WEEK__ · __SEASON__ · Results checked against Yahoo</span></div><div class="slides"></div><section class="how"><h2>One template. Every league. Every week.</h2><p>These are saved Week __WEEK__ results, using real player photos and team logos. Team of the Week selects only players who were started, including FLEX starters, and uses each league’s scoring. Awards are calculated from final matchup results.</p><p>Weekly draft workflow: capture completed results → validate lineups and scores → generate all thirty-six slides → review in Studio → download. Incomplete games, mismatched totals, missing images, and tied awards stop the export for review. Review every draft before posting. No social posts or app feed updates are created by this tool.</p><a class="pill" id="league-download" download>Download this league ↓</a></section></main><script>const leagues=MANIFEST;let selected=leagues[0].id;function show(id){selected=id;const l=leagues.find(x=>x.id===id);document.querySelector('.leagues').innerHTML=leagues.map(x=>`<button type="button" data-id="${x.id}" aria-pressed="${x.id===id}">${x.name}</button>`).join('');document.querySelectorAll('[data-id]').forEach(b=>b.onclick=()=>show(b.dataset.id));document.querySelector('#league-title').textContent=l.name;document.querySelector('.slides').innerHTML=l.slides.map((s,i)=>`<article class="slide"><a href="${s.png}" target="_blank"><img src="${s.preview || s.png}" alt="${l.name} ${s.title}"></a><div class="caption"><h3>${i+1}. ${s.title}</h3><a href="${s.png}" download>Download PNG ↓</a></div></article>`).join('');document.querySelector('#league-download').href=l.zip;}show(selected);</script></body></html>'''.replace('MANIFEST',data).replace('__WEEK__',str(week)).replace('__SEASON__',str(season))
(r/'studio-preview.html').write_text(page)
# Visual overview of all thirty-six finished slides for review.
body=''.join('<section><h2>'+lg['name']+'</h2><div>'+''.join('<img src="'+s['preview']+'">' for s in lg['slides'][:3])+'</div></section>' for lg in manifest)
(r/'contact.html').write_text('<html><head><style>body{margin:0;padding:24px;background:#0b121a;color:white;font-family:-apple-system}h2{font-size:20px;margin:8px 0 14px}section{margin-bottom:25px}section div{display:flex;gap:16px}img{width:432px;height:576px;object-fit:contain}</style></head><body>'+body+'</body></html>')
print('Packaged 36 PNGs, four individual ZIPs, a complete ZIP, and Studio · Drafts for review.')
